function pesan(menu: string, jumlah = 1, catatan?: string): string {
  const tambahan = catatan ? ` (${catatan})` : "";
  return `${jumlah}x ${menu}${tambahan}`;
}
function totalSemua(...harga: number[]): number {
  return harga.reduce((a, h) => a + h, 0);
}
console.log(pesan("Kopi"));
console.log(pesan("Teh", 2, "tanpa gula"));
console.log(totalSemua(18000, 12000, 5000), totalSemua());

