cards.solution:
function label(nama: string, harga: number, satuan = "pcs", ...tag: string[]): string {
  const bagianTag = tag.length > 0 ? ` [${tag.join(", ")}]` : "";
  return `${nama} ${harga}/${satuan}${bagianTag}`;
}
console.log(label("Gula", 14000, "kg", "promo", "baru"));
console.log(label("Pensil", 3000));
